<script setup lang="ts">import { reactive } from 'vue'; import AppHeader from '../../components/AppHeader.vue'; import BottomAction from '../../components/BottomAction.vue'; import { useAppStore } from '../../stores/app'; import { back } from '../../utils/ui'; const store=useAppStore();const d=new Date(Date.now()+86400000).toISOString().slice(0,10);const form=reactive({title:'',date:d,time:'19:00',location:'',count:4,minRating:'',maxRating:'',content:'',contact:''});async function submit(){if(!form.title||!form.location||!form.contact)return uni.showToast({title:'请填写标题、地点和联系方式',icon:'none'});const range=form.minRating||form.maxRating?`\n水平：${form.minRating||'不限'}–${form.maxRating||'不限'}`:'';try{await store.createPlayPost({title:form.title,content:`${form.content||'轻松练球，欢迎参加。'}${range}`,visibility:'PUBLIC',maxParticipants:Number(form.count),location:form.location,contact:form.contact,eventTime:new Date(`${form.date}T${form.time}:00+08:00`).toISOString()});back()}catch{}}</script>
<template><view class="app-shell no-tabs form-page"><AppHeader title="发起约球" backable/><view class="field"><text class="field-label">标题</text><input v-model="form.title" class="input" placeholder="今晚体育馆约球"/></view><view class="grid-two"><view class="field"><text class="field-label">日期</text><picker mode="date" :value="form.date" @change="form.date=$event.detail.value"><view class="select-field">{{ form.date }}</view></picker></view><view class="field"><text class="field-label">时间</text><picker mode="time" :value="form.time" @change="form.time=$event.detail.value"><view class="select-field">{{ form.time }}</view></picker></view></view><view class="field"><text class="field-label">地点</text><input v-model="form.location" class="input" placeholder="体育馆三楼"/></view><view class="field"><text class="field-label">人数</text><input v-model.number="form.count" class="input" type="number"/></view><view class="grid-two"><view class="field"><text class="field-label">最低积分（可选）</text><input v-model="form.minRating" class="input" type="number" placeholder="不限"/></view><view class="field"><text class="field-label">最高积分（可选）</text><input v-model="form.maxRating" class="input" type="number" placeholder="不限"/></view></view><view class="field"><text class="field-label">说明</text><textarea v-model="form.content" class="textarea" placeholder="补充器材、水平或其他说明"/></view><view class="field"><text class="field-label">联系方式</text><input v-model="form.contact" class="input" placeholder="加入后可联系你的方式"/></view><view v-if="store.error" class="notice notice-error">{{ store.error }}</view><BottomAction><button class="btn btn-primary btn-block" :disabled="store.loading" @click="submit">发布约球</button></BottomAction></view></template><style scoped>.form-page{padding-bottom:6.5rem}.field{margin-top:1rem}</style>
